import logging
import os

logger = logging.getLogger(__name__)

DSN = os.getenv("DATABASE_URL", "postgresql://catalogo:catalogo@postgres:5432/catalogo")


class ConsultaFalhou(Exception):
    def __init__(self, descricao, causa):
        super().__init__(f"falha na consulta '{descricao}' no catálogo: {causa}")
        self.descricao = descricao
        self.causa = causa


def consultar(sql, params=(), descricao="consulta"):
    """Roda o SELECT e devolve list[dict]."""
    import psycopg
    from psycopg.rows import dict_row

    try:
        with psycopg.connect(DSN, connect_timeout=5) as conexao:
            with conexao.cursor(row_factory=dict_row) as cursor:
                cursor.execute(sql, params)
                linhas = cursor.fetchall()
    except Exception as e:
        logger.error("consulta '%s' falhou no catálogo: %s", descricao, e, exc_info=True)
        raise ConsultaFalhou(descricao, e) from e

    logger.info("consulta '%s' devolveu %s linhas", descricao, len(linhas))
    return linhas


def um(sql, params=(), descricao="consulta"):
    """Primeira linha, ou None quando a consulta não devolve nada."""
    linhas = consultar(sql, params, descricao)
    return linhas[0] if linhas else None

